String tr(BuildContext context, String english) {
 final language = Localizations.localeOf(context).languageCode;
 final match = localizedLabels[english] ??
   (english.isEmpty ? null : localizedLabels[english[0].toUpperCase() + english.substring(1)]);
 return match?[language] ?? english;
}
class LanguagePicker extends StatelessWidget {
 const LanguagePicker({super.key,this.compact=false});
 final bool compact;
 @override Widget build(BuildContext context) {
  final app=AppScope.of(context);
  return DropdownButtonFormField<String>(
   key:ValueKey(app.languageCode),
   initialValue:app.languageCode,
   isExpanded:true,
   decoration:compact
      ? InputDecoration(
          isDense:true,
          filled:true,
          fillColor:const Color(0xFFFFF7FB),
          contentPadding:const EdgeInsets.symmetric(horizontal:10,vertical:10),
          prefixIcon:const Icon(Icons.language,size:20),
          labelText:tr(context,'Language'),
          border:OutlineInputBorder(borderRadius:BorderRadius.circular(18)),
        )
      : InputDecoration(labelText:tr(context,'Language'), prefixIcon:const Icon(Icons.language)),
   items:supportedLanguages.entries.map((e)=>DropdownMenuItem(
     value:e.key,child:Text(e.value,maxLines:1,overflow:TextOverflow.ellipsis,
       style:TextStyle(fontSize:compact?13:15)))).toList(),
   onChanged:(v) {if(v!=null)app.setLanguage(v);},
  );
 }
}
